import{_ as s,c as t,o as n,j as a,a as r}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"周易集传序","description":"汉上易传 - 周易集传序","frontmatter":{"title":"周易集传序","description":"汉上易传 - 周易集传序"},"headers":[],"relativePath":"zh/classics/hanshang/001.md","filePath":"zh/classics/hanshang/001.md"}'),l={name:"zh/classics/hanshang/001.md"};function c(o,e,i,d,h,p){return n(),t("div",null,[...e[0]||(e[0]=[a("h1",{id:"周易集传序",tabindex:"-1"},[r("周易集传序 "),a("a",{class:"header-anchor",href:"#周易集传序","aria-label":"Permalink to “周易集传序”"},"​")],-1),a("p",null,"汉上易傅四部丛刊续编经部上海涵芬楼景印北平图书馆藏宋刊本阙卷，以汲古阁影宋钞本配补。原书板高二十二公分，宽十五公分。",-1),a("p",null,"圣人观阴阳之变而立卦，效天下之动而生爻。变动之别，其传有五：曰动爻，曰卦变，曰互体，曰五行，曰纳甲。而卦变之中又有变焉：一三五，阳也；二四六，阴也。天地相函，坎离相交，谓之位。七，八者，阴阳之稚；六、九者，阴阳之究。稚，不变也，究则变焉，谓之策。七、八、九、六，或得或失，杂而成文，谓之爻。昔周人掌三易之法，一曰连山，二曰归藏，三曰周易。七、八者，连山、归藏也；六、九者，周易也。经实备之。策三变而成爻，爻六变而成位。变者以不变为体，不变者以变者为用。四象并行，八卦交错，而天地万物之情可见矣。其在系辞曰：爻象动乎内，吉凶见乎外。又曰：道有变动，故曰爻。此见于动爻者也。乾生三男，坤生三女。乾交乎坤，自姤至剥；坤交乎乾，自复至夬。十有二卦，谓之辟卦。坎、离、震、兑，谓之四正。四正之卦，分主四时。十有二卦，各主其月。乾贞于子而左行，坤贞于未而右行，左右交错，六十卦周天而复阴。阳之升降，四时之消息，天地之盈虚，万物之盛衰咸系焉。其在易之复曰七日来复。象曰至，日在。革，曰先王以治历明时。在说卦曰：震，东方也。巽，东南也。离，南方之卦也。兑，正秋也。乾，西北之卦也。坎，正北方之卦也。艮，东北之卦也。此见于卦变者也。乾生者四卦，坤生者四卦，八卦变复生六十二。坎、离，肖乾坤者也。大过、小过、颐、中孚，肖坎离者也。故乾、坤不动，而坎、离四卦亦莫之动。其略陈于杂卦，其详具于六十四卦之彖，所谓辨是与非者也。此卦变之中又有变焉者也。一卦含四卦，四卦之中复有变动，上下相揉，百物成象。其在易，则离、震合而有颐，坤、离具而生坎。在系辞，则罔罟取离，耒耨取益，为市取噬嗑，舟楫取涣，服乘取随，门柝取豫，杵臼取小过，弧矢取睽，栋宇取大壮，棺椁取大过，书契取夬。又曰：八卦相荡。又曰：六爻相杂，唯其时物也。又曰：杂物撰德。此见于互体者也。一生水而成六，二生火而成七，三生木而成八，四生金而成九，五生土而成十。生于阳者成于阴，三天两地也。生于阴者成于阳，两地而三天也。天以三兼二，地以二兼三，五位相得，合而为五十。其在系辞曰：",-1),a("p",null,"天一地二，天三地四，天五地六，天七地八，天九地十。在说卦曰：巽为木，坎为水，离为火。此见于五行者也。乾纳甲壬，坤纳乙癸，震纳庚，巽纳辛，坎纳戊，离纳己，艮纳丙，兑纳丁。庚、戊、丙三者，得于乾者也。辛、己、丁三者，得于坤者也。始于甲乙，终于壬癸，而天地五十五数具焉。其在易之蛊曰：先甲三日，后甲三日。在巽曰先庚三日，后庚三日。在离，曰：己日乃孚。在系辞曰：悬象著明，莫大于日月。此见于纳甲者也。凡此五者之变，自一二三四言之谓之数，自有形无形言之谓之象，自推考象数言之谓之占。圣人无不该也，无不徧也，随其变而言之谓之辞。辞也者，所以明道也。故辞之所指，变也，象数也，占也，无不具焉。是故可以动，可以言，可以制器，可以卜筮。盖不如是，不足以明道之变动而尽夫时中也。故曰系辞焉而命之，动在其中矣。夫易广矣大矣，其远不可御矣。然不越乎阴阳二端，其究则一而巳矣。一者，天地之根本也，万物之权舆也。阴阳，动静之源也，故谓之太极。学至于此止矣。卦可遗也，爻可忘也，五者之变，反于一也。是故圣人之辞，因是而止矣。",-1)])])}const f=s(l,[["render",c]]);export{_ as __pageData,f as default};
